[IO.File]::WriteAllText((Join-Path $PWD 'check-attachment.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Fetches one MIME part of a stored message over IMAP, decodes it from base64 and compares`n# its bytes with a file. Usage: sh check-attachment.sh <user:password> <part URL> <file>`ncurl -sS -u `"`$1`" `"`$2`" -o part.b64 || exit `$?`nif [ ! -s part.b64 ]; then`n  echo `"no such part`"`n  exit 1`nfi`ntr -d '\r' < part.b64 | base64 -d > part.bin || exit 1`nif cmp -s part.bin `"`$3`"; then`n  echo `"attachment matches `$3, `$(wc -c < `"`$3`" | tr -d ' ') bytes`"`nelse`n  echo `"attachment differs from `$3`"`n  exit 1`nfi`n")
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'app@example.com:apppass', '--mailbox', 'ann@example.com:annpass', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
