try { curl.exe --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt ann@example.com -T report-mail.eml smtp://127.0.0.1:8080/example.com && sh check-attachment.sh ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=2" report.csv } finally { Stop-Process $server0 }
